// Package demo holds the sample GTFS feed the demo environment runs on
// (docs/demo.md). gtfs.zip is generated by the builder in this file; do not
// edit it by hand.
package demo

import (
	"archive/zip"
	"bytes"
	"fmt"
	"math"
	"os"
	"slices"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/OneBusAway/vehicle-positions/rider"
)

const (
	feedPath     = "gtfs.zip"
	feedTimezone = "Africa/Nairobi"

	// A trip leaves each terminal every headway, around the clock. The server's
	// service day runs from 03:00 to 03:00 (rider.Index.ServiceDate), so
	// departures up to 27:00:00 put a trip on the road at every hour of every
	// day. They start an hour before 03:00 so that trips are already running
	// in both directions at the moment the service day changes.
	headway        = 15 * time.Minute
	firstDeparture = 2 * time.Hour
	lastDeparture  = 27 * time.Hour

	cruiseSpeed = 7.0 // metres per second between stops, about 25 km/h
	dwell       = 20 * time.Second
	// minLayover is the shortest wait at the outer terminal before the trip
	// back, so a vehicle that finishes a trip has the next one to take.
	minLayover = 3 * time.Minute
)

// demoRoute is one line of the fictional agency: a shape from the city centre
// outwards, driven in both directions, with its stops spaced evenly along it.
type demoRoute struct {
	id        string
	shortName string
	longName  string
	color     string
	stops     []string     // stop names from the city centre outwards
	shape     [][2]float64 // latitude, longitude
}

