// buildFeed renders the demo feed. The bytes are identical across runs: zip
// entries are written in a fixed order with a zero modification time.
func buildFeed(t *testing.T) []byte {
	t.Helper()

	var routes, stops, shapes, trips, stopTimes strings.Builder
	routes.WriteString("route_id,agency_id,route_short_name,route_long_name,route_type,route_color,route_text_color\n")
	stops.WriteString("stop_id,stop_name,stop_lat,stop_lon\n")
	shapes.WriteString("shape_id,shape_pt_lat,shape_pt_lon,shape_pt_sequence,shape_dist_traveled\n")
	trips.WriteString("route_id,service_id,trip_id,shape_id,trip_headsign,direction_id\n")
	stopTimes.WriteString("trip_id,arrival_time,departure_time,stop_id,stop_sequence,shape_dist_traveled\n")

	for _, r := range demoRoutes {
		fmt.Fprintf(&routes, "%s,DEMO,%s,%s,3,%s,FFFFFF\n", r.id, r.shortName, r.longName, r.color)

		points := make([]rider.LatLon, len(r.shape))
		for i, p := range r.shape {
			points[i] = rider.LatLon{Lat: p[0], Lon: p[1]}
		}
		outbound := rider.NewShapeGeom(points)
		spacing := outbound.Length / float64(len(r.stops)-1)
		for i, name := range r.stops {
			pos := outbound.PointAt(float64(i) * spacing)
			fmt.Fprintf(&stops, "%s,%s,%s,%s\n", stopID(r, i), name, coord(pos.Lat), coord(pos.Lon))
		}

		// The trip back leaves the outer terminal minLayover after a trip out
		// arrives there, on the next whole minute.
		tripTime := time.Duration(len(r.stops)-1)*legTime(spacing) + time.Duration(len(r.stops)-2)*dwell
		inboundOffset := (tripTime + minLayover).Truncate(time.Minute) + time.Minute

		for direction, headsign := range []string{r.stops[len(r.stops)-1], "City Centre"} {
			shapeID := fmt.Sprintf("%s-%d", r.id, direction)
			geom, offset := outbound, time.Duration(0)
			if direction == 1 {
				reversed := slices.Clone(points)
				slices.Reverse(reversed)
				geom, offset = rider.NewShapeGeom(reversed), inboundOffset%headway
			}
			for i, p := range geom.Points {
				fmt.Fprintf(&shapes, "%s,%s,%s,%d,%s\n", shapeID, coord(p.Lat), coord(p.Lon), i+1, metres(geom.Cumulative[i]))
			}

			for departure := firstDeparture + offset; departure < lastDeparture; departure += headway {
				tripID := fmt.Sprintf("%s-%d-%s", r.id, direction, strings.ReplaceAll(clock(departure)[:5], ":", ""))
				fmt.Fprintf(&trips, "%s,DAILY,%s,%s,%s,%d\n", r.id, tripID, shapeID, headsign, direction)

				arrival := departure
				for seq := range r.stops {
					stop := seq
					if direction == 1 {
						stop = len(r.stops) - 1 - seq
					}
					leave := arrival
					if seq > 0 && seq < len(r.stops)-1 {
						leave += dwell
					}
					fmt.Fprintf(&stopTimes, "%s,%s,%s,%s,%d,%s\n",
						tripID, clock(arrival), clock(leave), stopID(r, stop), seq+1, metres(float64(seq)*spacing))
					arrival = leave + legTime(spacing)
				}
			}
		}
	}

	files := []struct{ name, body string }{
		{"agency.txt", "agency_id,agency_name,agency_url,agency_timezone\n" +
			"DEMO,Demo Transit,https://github.com/OneBusAway/vehicle-positions," + feedTimezone + "\n"},
		{"routes.txt", routes.String()},
		{"calendar.txt", "service_id,monday,tuesday,wednesday,thursday,friday,saturday,sunday,start_date,end_date\n" +
			"DAILY,1,1,1,1,1,1,1,20260101,20351231\n"},
		{"shapes.txt", shapes.String()},
		{"stops.txt", stops.String()},
		{"trips.txt", trips.String()},
		{"stop_times.txt", stopTimes.String()},
	}

	var buf bytes.Buffer
	w := zip.NewWriter(&buf)
	for _, f := range files {
		entry, err := w.CreateHeader(&zip.FileHeader{Name: f.name, Method: zip.Deflate})
		require.NoError(t, err)
		_, err = entry.Write([]byte(f.body))
		require.NoError(t, err)
	}
	require.NoError(t, w.Close())
	return buf.Bytes()
}

func stopID(r demoRoute, i int) string { return fmt.Sprintf("%s-S%d", r.id, i+1) }

// legTime is the scheduled time between two stops, in whole seconds.
func legTime(metres float64) time.Duration {
	return time.Duration(math.Round(metres/cruiseSpeed)) * time.Second
}

// clock renders a time since service-day midnight as GTFS "HH:MM:SS", which
// runs past 24:00:00 for the hours after midnight.
func clock(d time.Duration) string {
	s := int(d.Seconds())
	return fmt.Sprintf("%02d:%02d:%02d", s/3600, s%3600/60, s%60)
}

func coord(v float64) string  { return strconv.FormatFloat(v, 'f', 6, 64) }
func metres(v float64) string { return strconv.FormatFloat(v, 'f', 1, 64) }

// TestWriteFeed regenerates gtfs.zip when WRITE_DEMO_FEED=1 and otherwise
// asserts the committed file still matches the builder above.
func TestWriteFeed(t *testing.T) {
	b := buildFeed(t)
	if os.Getenv("WRITE_DEMO_FEED") == "1" {
		require.NoError(t, os.WriteFile(feedPath, b, 0o644))
		return
	}
	onDisk, err := os.ReadFile(feedPath)
	require.NoError(t, err, "run WRITE_DEMO_FEED=1 go test ./demo -run TestWriteFeed")
	assert.True(t, bytes.Equal(b, onDisk), "committed demo feed drifted; regenerate it with WRITE_DEMO_FEED=1")
}

// committedIndex indexes the committed feed the way the server does at startup.
func committedIndex(t *testing.T) *rider.Index {
	t.Helper()
	body, err := os.ReadFile(feedPath)
	require.NoError(t, err)
	ix, err := rider.IndexFromBytes(body, feedPath, time.Now())
	require.NoError(t, err)
	return ix
}

// TestFeedIndexesEveryTrip: the server's index drops a trip it cannot use (no
// shape, no stop times), and the catalog only lists routes that kept one.
func TestFeedIndexesEveryTrip(t *testing.T) {
	ix := committedIndex(t)

	departures := int((lastDeparture - firstDeparture) / headway)
	stats := ix.Stats()
	assert.Equal(t, len(demoRoutes), stats.Routes)
	assert.Equal(t, len(demoRoutes)*2*departures, stats.Trips)
	assert.Equal(t, feedTimezone, ix.Timezone().String())

	for _, r := range demoRoutes {
		trip, ok := ix.Trip(r.id + "-0-0800")
		require.True(t, ok, "route %s has no 08:00 trip out", r.id)
		assert.False(t, trip.ShapeFromStops)
		require.Len(t, trip.StopTimes, len(r.stops))
		last := trip.StopTimes[len(trip.StopTimes)-1]
		assert.Equal(t, r.stops[len(r.stops)-1], last.StopName)
		assert.InDelta(t, trip.Shape.Length, last.AlongShape, 1, "the last stop is the end of the shape")
	}
}

// TestFeedHasATripRunningAtAnyHour pins what the demo depends on: whenever it
// is started, every route has a trip on the road in each direction for the
// simulator to drive. A week of five-minute steps covers every weekday, the
// 03:00 service-day change and midnight.
func TestFeedHasATripRunningAtAnyHour(t *testing.T) {
	ix := committedIndex(t)
	start := time.Date(2026, 11, 9, 0, 0, 0, 0, ix.Timezone())

	for at := start; at.Before(start.AddDate(0, 0, 7)); at = at.Add(5 * time.Minute) {
		date := ix.ServiceDate(at)
		dayStart, err := rider.ServiceDayStart(date, ix.Timezone())
		require.NoError(t, err)

		for _, r := range demoRoutes {
			running := map[int]bool{}
			for _, trip := range ix.TripsOnRoute(r.id, date) {
				departs := dayStart.Add(trip.StopTimes[0].Departure)
				arrives := dayStart.Add(trip.StopTimes[len(trip.StopTimes)-1].Arrival)
				if !at.Before(departs) && at.Before(arrives) {
					running[trip.DirectionID] = true
				}
			}
			require.True(t, running[0] && running[1],
				"route %s at %s: running out=%t back=%t", r.id, at.Format(time.RFC1123), running[0], running[1])
		}
	}
}

// TestFeedLayoverIsShort: a vehicle that reaches the outer terminal must find a
// trip back leaving within a few minutes, or it sits there instead of moving.
func TestFeedLayoverIsShort(t *testing.T) {
	ix := committedIndex(t)

	for _, r := range demoRoutes {
		out, ok := ix.Trip(r.id + "-0-0800")
		require.True(t, ok)
		arrives := out.StopTimes[len(out.StopTimes)-1].Arrival

		wait := time.Duration(math.MaxInt64)
		for _, trip := range ix.TripsOnRoute(r.id, "20261109") {
			if trip.DirectionID != 1 {
				continue
			}
			if w := trip.StopTimes[0].Departure - arrives; w >= 0 && w < wait {
				wait = w
			}
		}
		assert.GreaterOrEqual(t, wait, minLayover, "route %s", r.id)
		assert.Less(t, wait, minLayover+time.Minute, "route %s", r.id)
	}
}
